function srvAlicePick(html) {
    var h = String(html || "");
    var cands = [];
    var res = [/<div[^>]*class="[^"]*read-content[^"]*"[^>]*>([\s\S]*)/i,
               /<div[^>]*class="[^"]*page-read[^"]*"[^>]*>([\s\S]*)/i];
    for (var i = 0; i < res.length; i++) {
        var m = h.match(res[i]);
        if (!m) continue;
        var seg = m[1];
        var cut = seg.length;
        var stops = [/<div[\s>]/i, /<footer/i, /<\/body/i, /<!--\s*end/i, /<script/i];
        for (var k = 0; k < stops.length; k++) {
            var mm = seg.search(stops[k]);
            if (mm > 200 && mm < cut) cut = mm;
        }
        var ps = seg.match(/<p[^>]*>[\s\S]*?<\/p>/gi);
        var part = (ps && ps.length >= 3) ? ps.join("\n") : seg.slice(0, cut);
        var t = part
            .replace(/<br\s*\/?>/gi, "\n").replace(/<\/p>/gi, "\n")
            .replace(/<[^>]*>/g, "").replace(/&nbsp;/g, " ").replace(/&amp;/g, "&")
            .replace(/&lt;/g, "<").replace(/&gt;/g, ">").replace(/&quot;/g, '"');
        var lines = t.split("\n").map(function (x) { return x.replace(/[ \t\u3000]+/g, " ").trim(); }).filter(Boolean);
        cands.push(lines.join("\n"));
    }
    var best = "";
    for (var j = 0; j < cands.length; j++) if (cands[j] && cands[j].length > best.length) best = cands[j];
    return best.length > 100 ? best : "";
}
