function fqVideoStreamJson(itemId, site, tab, bookId) {
    try {
        var plat = (tab === "13" || tab === "19") ? "hgmd" : "hgds";
        var u = srvBase() + "/public/" + plat + "/content?url=" + encodeURIComponent(String(itemId))
              + "&platform=" + plat + (bookId ? ("&bid=" + encodeURIComponent(String(bookId))) : "");
        var j = srvJson(u);
        if (!j || !j.ok) { return JSON.stringify({ err: (j && j.err) || "取流失败" }); }
        var dd = j.data || j;
        var vu = String(dd.url || dd.content || "");
        if (!vu) { return JSON.stringify({ err: "空视频地址" }); }
        return JSON.stringify({ url: vu, keyHex: String(dd.keyHex || ""), size: Number(dd.size) || 0 });
    } catch (e) {
        return JSON.stringify({ err: String(e && e.message || e) });
    }
}

