// ==================== UAA 有声 · 本地直连（不经服务器，用户自开代理） ====================
// 为什么直连：UAA 是 Cloudflare 站点且对数据中心 IP 做 SNI 阻断 —— 服务器（腾讯云）与
// 本机终端都连不上，只有用户设备开代理才能访问。所以该平台全部请求由客户端发起。
// 已实测接口（2026-10-17，代理出口 209.9.200.205）：
//   搜索 /api/audio/app/audio/search?...            → model.data[]
//   详情 /api/audio/app/audio/intro?id=             → model（对象本身）
//   目录 /api/audio/app/audio/catalog/{id}          → model.menus[]
//   正文 /api/audio/app/audio/chapter?force=false&id={chId}&offset=0&viewId={ts} → model.url（mp3 直链）
// 注意：正文接口会回 code=1 "请先登录"，但 model.url 照样返回（未登录可听）。
// token 走 Legado 的 URL 附加头语法（",{\"headers\":{...}}"），避免依赖源级统一 header。
var UAA_HOSTS = ["https://www.uaa001.com", "https://www.uaa.com", "https://www.uaa002.com",
                 "https://www.uaa003.com", "https://www.uaa004.com", "https://www.uaa005.com",
                 "https://www.uaa202410.com"];
function uaaHost() {
    try { var h = String(srvVar()["uaaHost"] || ""); if (h) return h.replace(/\/+$/, ""); } catch (e) { }
    return UAA_HOSTS[0];
}
function uaaToken() { try { return String(srvVar()["uaaToken"] || ""); } catch (e) { return ""; } }
function uaaHdr() {
    var h = { "User-Agent": "Mozilla/5.0 (Linux; Android 13; PFJM10) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Mobile Safari/537.36",
              "Accept": "application/json, text/plain, */*" };
    var t = uaaToken();
    if (t) h["token"] = t;
    return h;
}
// uaaUrl: 给 Legado 直连用的 URL（带附加头）
function uaaUrl(path) {
    var u = uaaHost() + path;
    try { return u + ",{\"headers\":" + JSON.stringify(uaaHdr()) + "}"; } catch (e) { return u; }
}
// uaaGet: 在 @js: 里取 JSON（同样走附加头）。返回 {model:...} 或 {err:"..."}
function uaaGet(path) {
    var raw = "";
    try { raw = String(srvJav().ajax(uaaUrl(path), 20000)); } catch (e) {
        return { err: "UAA 连不上（该站需自开代理）：" + String(e) };
    }
    if (!raw) return { err: "UAA 没有响应（请确认代理已开启）" };
    var o = null;
    try { o = JSON.parse(raw); } catch (e2) { return { err: "UAA 返回异常：" + raw.substring(0, 120) }; }
    // code=0 正常；code=1 "请先登录" 时正文仍可用（model.url 有值），故有 model 就放行
    if (o && o.model === undefined && o.code !== undefined && o.code !== 0) {
        return { err: String(o.msg || "UAA 返回错误(" + o.code + ")") };
    }
    return o;
}
// uaaData: 从响应里抽数组（model.data / model 是数组 / model.menus）
function uaaData(o, key) {
    if (!o) return [];
    var m = o.model;
    if (m === undefined || m === null) m = o.data;
    var t = Object.prototype.toString;
    if (t.call(m) === "[object Array]") return m;
    if (m && typeof m === "object") {
        if (key && t.call(m[key]) === "[object Array]") return m[key];
        if (t.call(m.data) === "[object Array]") return m.data;
        if (t.call(m.menus) === "[object Array]") return m.menus;
        if (t.call(m.list) === "[object Array]") return m.list;
    }
    if (t.call(o.data) === "[object Array]") return o.data;
    return [];
}
function uaaItemMap(b) {
    var id = String(b.id || b.audioId || "");
    var fin = String(b.finished);
    return {
        name: String(b.title || b.name || ""),
        author: String(b.authors || b.author || "UAA"),
        kind: (fin === "1" ? "完结" : "连载") + (b.categories ? ("," + String(b.categories)) : "") +
              (b.chapterCount ? (" · " + String(b.chapterCount) + "集") : ""),
        wordCount: String(b.durationFormat || ""),
        lastChapter: String(b.latestUpdate || b.updateTimeFormat || ""),
        intro: String(b.brief || b.description || ""),
        coverUrl: String(b.coverUrl || b.cover || ""),
        bookUrl: (function(_id){var _u=uaaHost()+"/api/audio/app/audio/intro?id="+encodeURIComponent(_id);
                  try{ return _u+",{\"headers\":"+JSON.stringify({"User-Agent":"Mozilla/5.0 (Linux; Android 13; PFJM10) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Mobile Safari/537.36","Accept":"application/json, text/plain, */*"})+"}"; }
                  catch(_e){ return _u; } })(id)
    };
}
function uaaSearchMap(o) {
    var arr = uaaData(o, "data");
    var out = [];
    for (var i = 0; i < arr.length; i++) {
        var b = arr[i] || {};
        if (!b.title && !b.name) continue;
        out.push(uaaItemMap(b));
    }
    return out;
}
// ---- 前缀标记（贯穿书源各处路由）----
function uaaIsBook(u) { return String(u || "").indexOf("uaa:") === 0; }
function uaaIsToc(u) { return String(u || "").indexOf("uaa-toc:") === 0; }
function uaaIsCh(u) { return String(u || "").indexOf("uaa-c:") === 0; }
// uaaInfo 详情：id 形如 "131...,{\"headers\":...}"（带附加头的真实 URL 传进来）
// raw = Legado 抓到的响应体。result 为空时回退 uaaGet 兜底
var uuaP_shown = 0;
function uaaInfoPathArg(arg) {
    var id = String(arg || "");
    // 去掉尾部的 ,{"headers":...} 附加段
    var m = id.match(/^(.*?),\s*\{[\s\S]*$/);
    return m ? m[1] : id;
