    try { page = String(srvP_var()["panelPage"] || ""); } catch (e) { page = ""; }
    if (page === "plat") {
        var kind = srvReadKindP();
        var mode = srvReadMode();
        out.push({ name: "← 返回", type: "button", action: "srvPage('')",
                   style: { layout_flexGrow: 1, layout_flexBasisPercent: 1 } });
