            out.push({ name: (mode === pl.id ? "✅ " : "") + pl.name, type: "button",
                       action: "srvSetMode('" + pl.id + "')",
                       style: { layout_flexGrow: 0.4, layout_flexBasisPercent: 0.4 } });
        }
