                           style: { layout_flexGrow: 1, layout_flexBasisPercent: 1 } });
        return out;
    }

    var kindNow = srvReadKindP();
    var isAudio = (kindNow === "audio"), isDrama = (kindNow === "drama");
    var isComic = (kindNow === "comic"), isAdult = (kindNow === "adult");
