            if (isText && String(r.action || "").indexOf("srvKindPage('')") >= 0) hit = true;
            else if (isAudio && String(r.action || "").indexOf("srvKindPage('audio')") >= 0) hit = true;
            else if (isDrama && String(r.action || "").indexOf("srvKindPage('drama')") >= 0) hit = true;
            else if (isComic && String(r.action || "").indexOf("srvKindPage('comic')") >= 0) hit = true;
            else if (isAdult && String(r.action || "").indexOf("srvKindPage('adult')") >= 0) hit = true;
        }
        if (hit) out.push({ name: "✅ " + r.name, type: r.type, action: r.action, style: r.style });
        else out.push(r);
    }
    return out;
}

